{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.Xquik-dev/tweetclaw",
  "description": "Search tweets, search replies, post tweets, export followers, manage media, monitor X/Twitter, and run giveaway draws through Xquik. OpenClaw plugin with 99 agent-callable endpoints via 2 tools (explore + tweetclaw). StreamableHTTP at xquik.com/mcp with API key auth.",
  "repository": {
    "url": "https://github.com/Xquik-dev/tweetclaw",
    "source": "github"
  },
  "version": "1.6.32",
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://xquik.com/mcp",
      "authentication": {
        "type": "api-key",
        "header": "X-API-Key",
        "description": "Xquik API key (prefix xq_). Get one at dashboard.xquik.com."
      }
    }
  ]
}
